WITH src AS (SELECT *, DATE_FORMAT(signup_date, 'yyyy-MM-dd') AS signup_date_label FROM customers WHERE NOT (LENGTH(email) < 12 AND credit_limit > 15000)), segment_summary AS (SELECT segment, DATE_FORMAT(signup_date, 'yyyy-MM') AS signup_month, MAX(signup_date) AS last_signup_date, MAX(credit_limit) AS max_credit_limit FROM src GROUP BY segment, DATE_FORMAT(signup_date, 'yyyy-MM')) SELECT segment, signup_month, max_credit_limit FROM segment_summary WHERE max_credit_limit >= 11500
